SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷五十一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/jiuwudaishi-051-li-congyi/source.txt", "note": "《旧五代史》卷五十一，段落 jiu-wudaishi-205deb4a7860-p001387；EPUB电子本，纸本及异文待核", "id": "7ff2a823-7208-54e1-a2ef-e7ec344ed66c"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/jiuwudaishi-099-march-rising/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002428；EPUB电子本，纸本及异文待核", "id": "1b396d07-3d8c-5388-8d7c-afd93f0c779b"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/tongjian-286-947-xuzhou-march/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003400；电子底本待考，分段待核", "id": "a967c8c3-a86b-5a6a-935c-f02f4127bba5"}, {"title": "新五代史·卷四十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/xinwudaishi-040-gao-yunquan/source.txt", "note": "《新五代史》卷四十，段落 xin-wudaishi-b08f244b9241-p001448；EPUB电子本，纸本及异文待核", "id": "d7bffab9-6e67-5f1f-819d-babc505b7afd"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c55e23db2fe30e337126197