INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}, {"name": "周密（后晋节度使）", "aliases": ["周密（後晉節度使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州人，后晋彰武节度使。947年延州将士攻他，战败后退保东城，与获推留后的高允权分据两城。与南宋同名作者区分，生卒年未载。", "biography": null, "status": "draft", "id": "798acc84-ada0-59ce-83be-19bc78b46946"}, {"name": "高允权", "aliases": ["高允權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高万金之子。947年延州军队攻周密，高允权获推为留后、据西城。《通鉴》称录事参军，《新五代史》追记开运时任肤施令、罢后居家，任职时点及写法分别保留。生卒年暂未录入。", "biography": null, "status": "draft", "id": "be6f380e-7cd3-5e5e-87d2-900104d55f65"}, {"name": "高万金", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：高万金。", "biography": null, "status": "draft", "id": "b616c7c9-ce87-578d-8883-915f74f54099"}, {"name": "高彦珣", "aliases": ["高彥珣", "高彦询", "高彥詢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "丹州都指挥使。947年杀契丹委任的刺史，自管州务。当前《通鉴》此段写高彦珣，后段及《新五代史》写高彦询，《旧五代史》写高彥珣，依同一职务与事件识别为同人，引用保留各书字形。生卒年未载。", "biography": null, "status": "draft", "id": "f45f73c5-bcad-5722-933f-706d070dc315"}, {"name": "述律平", "aliases": ["述律氏", "述律后", "述律皇后"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：述律平。", "biography": null, "status": "draft", "id": "1c865dcb-3259-50e9-b13e-181615308183"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "李氏（赵延寿继室）", "aliases": ["李氏（趙延壽繼室）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后唐明宗李嗣源的小女儿。947年赵延寿在大梁娶她为继室，王淑妃赴大梁参与婚礼。与此前赵延寿妻兴平公主区分，未据本段补封号、名字或生卒年。", "biography": null, "status": "draft", "id": "7fa608aa-718c-55f3-aeb1-60b15666fcb3"}, {"name": "王淑妃", "aliases": ["花见羞", "花見羞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王淑妃，为求出所借宫中渠道。", "biography": null, "status": "draft", "id": "db6392e5-1b9a-5a9d-a338-bcfe97719238"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "刘遂凝", "aliases": ["劉遂凝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘遂凝，秘密联系、上表者。", "biography": null, "status": "draft", "id": "d0a76696-a356-5c94-923b-db6f5d0e6162"}, {"name": "李从益", "aliases": ["李從益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李从益，获许王爵者。", "biography": null, "status": "draft", "id": "2d5dc982-595f-53af-8762-1255e0d9723d"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张砺。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "刘昫", "aliases": ["劉昫", "刘煦", "劉煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘昫，端明殿学士、受相职者。", "biography": null, "status": "draft", "id": "b63eeed9-ecc3-575d-aba8-41b03e6caa3e"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "李仁恕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年率数万人攻徐州的武装首领，曾拉住符彦卿的马，想随他进城。陈守习公开表示徐州不会因符彦卿被困而投降后，李仁恕一方请赦，誓约后撤去。生卒年未载。", "biography": null, "status": "draft", "id": "6ce03d79-ca29-5978-ba82-86893f1ae341"}, {"name": "符昭序", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "符彦卿之子。947年守徐州城时，遣军校陈守习缒城而出，公开说明即使符彦卿受胁迫，攻城也不能得逞。生卒年未载。", "biography": null, "status": "draft", "id": "16db927f-e104-5b68-bf20-9b02757ae611"}, {"name": "陈守习", "aliases": ["陳守習"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐州军校。947年受符昭序派遣，从城中缒下，到攻城武装中喊话，表明城池不会因符彦卿受制而交出。生卒年未载。", "biography": null, "status": "draft", "id": "8c637d4c-f9de-5fe5-a6ce-d05624fa9e53"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
